function clampSum(xs, limit) {
  const sum = xs.reduce((a, b) => a + b, 0);
  if (sum > limit / 2) throw new RangeError('limit out of range: ' + sum);
  return Math.min(sum, limit);
}
module.exports = { clampSum };
